/**
 * Sliced known-answer vectors for the nine NIST lightweight finalists.
 *
 * GENERATED, not written. The submissions' own KAT files hold 1089 AEAD records each -- every message
 * length 0..32 crossed with every associated-data length 0..32 -- and 1025 hash records. Committing all
 * of them for fourteen algorithms would be megabytes; committing a handful would miss the rate
 * boundaries, which is precisely where a sponge or a padding rule goes wrong.
 *
 * So the selection is by *length* rather than by sampling: every rate boundary in the family and one
 * either side (the rates are 4, 8, 16, 18, 20, 22, 24 and 25 bytes), taken three ways -- message only,
 * associated data only, and both at once. Same discipline as `tests/ascon-kat.ts`.
 *
 * Sources: `bc-test-data` for eight of the nine, which mirrors the submission packages verbatim, and
 * rweather/TinyJAMBU for the ninth, which Bouncy Castle does not carry.
 *
 * The full files were run against every implementation during development -- 53,000 assertions with one
 * failure, PHOTON-Beetle-Hash at exactly sixteen bytes. What is committed here is what the suite runs
 * on every change.
 */

export interface LwcAeadVector {
  /** The record number in the source file, so a failure can be traced back. */
  count: number;
  key: string;
  nonce: string;
  /** Plaintext; empty string for the zero-length case. */
  pt: string;
  ad: string;
  /** Ciphertext with the tag appended, as the KAT files write it. */
  ct: string;
}

export interface LwcHashVector {
  count: number;
  msg: string;
  md: string;
}

